mapper.select:
select t.service_price,t.service_price servicePrice,t.create_time,t.create_time
createTime,t.price,t.cpa_id,t.cpa_id cpaId,t.remark,t.status_cd,t.status_cd statusCd,t.rule_id,t.rule_id
ruleId,t.type,td.`name` typeName,t.community_id,t.community_id communityId
from charge_peak_alley_price t
left join t_dict td on td.status_cd = t.type and td.table_name = 'charge_peak_alley_price' and td.table_columns
= 'type'
where 1 =1

    and t.service_price= #{servicePrice}


    and t.create_time= #{createTime}


    and t.price= #{price}


    and t.cpa_id= #{cpaId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.rule_id= #{ruleId}


    and t.type= #{type}


    and t.community_id= #{communityId}

order by t.type asc,t.create_time desc

    limit #{page}, #{row}

mapper.update:
update charge_peak_alley_price t set t.status_cd = #{statusCd}

    , t.service_price= #{servicePrice}


    , t.create_time= #{createTime}


    , t.price= #{price}


    , t.cpa_id= #{cpaId}


    , t.remark= #{remark}


    , t.type= #{type}


    , t.community_id= #{communityId}

where 1=1

    and t.rule_id= #{ruleId}

mapper.select:
select count(1) count
from charge_peak_alley_price t
where 1 =1

    and t.service_price= #{servicePrice}


    and t.create_time= #{createTime}


    and t.price= #{price}


    and t.cpa_id= #{cpaId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.rule_id= #{ruleId}


    and t.type= #{type}


    and t.community_id= #{communityId}
